#include "p4pc/content_source.h"
#include "p4pc/content_digest.h"
#include "p4pc/ps2_libc.h"
#include <stdio.h>
#include <string.h>
#define CHECK(x) do { if (!(x)) { fprintf(stderr,"content_source:%d: %s\n",__LINE__,#x); return 1; } } while (0)

static int digest_vectors(void)
{
    /* Standard SHA-256 example messages, not generated by this implementation. */
    static const struct { const char *text, *hex; } vectors[]={
        {"","e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},
        {"abc","ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"},
        {"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq",
         "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"},
        {"abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmn"
         "hijklmnoijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu",
         "cf5b16a778af8380036ce59e7b0492370b249b11e8f07a51afac45037afee9d1"}
    };
    P4ContentDigest state;
    char hex[P4_CONTENT_DIGEST_HEX+1];
    uint8_t block[1000];
    for (size_t i=0;i<sizeof vectors/sizeof *vectors;++i) {
        size_t size=strlen(vectors[i].text);
        p4_content_digest(vectors[i].text,size,hex);
        CHECK(strcmp(hex,vectors[i].hex)==0);
        for (size_t split=0;split<=size;++split) {
            p4_content_digest_begin(&state);
            p4_content_digest_update(&state,NULL,0);
            p4_content_digest_update(&state,vectors[i].text,split);
            p4_content_digest_update(&state,NULL,0);
            p4_content_digest_update(&state,vectors[i].text+split,size-split);
            p4_content_digest_end(&state,hex);
            CHECK(strcmp(hex,vectors[i].hex)==0);
        }
    }
    memset(block,'a',sizeof block);
    p4_content_digest_begin(&state);
    for (unsigned i=0;i<1000;++i)
        p4_content_digest_update(&state,block,sizeof block);
    p4_content_digest_end(&state,hex);
    CHECK(strcmp(hex,"cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0")==0);
    return 0;
}

int main(void)
{
    uint8_t input[32], output[32];
    static uint8_t chunks[65536+4], many[4097*4];
    P4ContentSource disc={P4_TEXTURE_DISC,0,0,0,"disc","DATA/TEXTURE.TMX"};
    P4ContentSource mod={P4_TEXTURE_OVERRIDE,3,0,0,"example.mod","DATA/TEXTURE.TMX"};
    P4ContentSource result;
    P4ContentReadScope outputScope;
    P4ContentRaster *raster=NULL;
    P4ContentSource authored;
    CHECK(p4_content_raster_set(&raster,&disc)==0 && raster);
    CHECK(p4_content_source_same(&raster->source,&disc));
    CHECK(!p4_content_source_same(&raster->source,&mod));
    CHECK(!p4_content_source_authored(&authored,&disc));
    CHECK(!p4_content_source_authored(NULL,&disc));
    CHECK(p4_content_source_authored(NULL,&mod));
    CHECK(p4_content_source_authored(&authored,&mod));
    CHECK(p4_content_source_same(&authored,&mod));
    CHECK(p4_content_raster_set(&raster,&authored)==0);
    CHECK(p4_content_source_same(&raster->source,&mod));
    p4_content_raster_free(raster);
    CHECK(digest_vectors()==0);
    p4pc_bytes_invalidate(NULL,UINT32_MAX); /* disabled: no pointer inspection */
    CHECK(!p4_content_source_find(input,sizeof input,&result));
    p4_content_source_mark(NULL,SIZE_MAX,&disc); /* disabled: no pointer inspection */
    CHECK(p4_content_sources_enable(1,NULL)==0);
    p4_content_sources_assert_owner();
    p4_content_host_read_begin(&outputScope,output,sizeof output);
    CHECK(p4_content_host_read_contains(output+7,4));
    CHECK(!p4_content_host_read_contains(output+31,2));
    CHECK(p4_content_sources_enabled);
    for (size_t i=0;i<sizeof input;++i) input[i]=(uint8_t)i;
    p4_content_source_mark(input,16,&disc);
    p4_content_source_mark(input+16,16,&disc);
    CHECK(p4_content_source_find(input,32,&result));
    CHECK(result.origin==P4_TEXTURE_DISC && strcmp(result.key,disc.key)==0);
    CHECK(p4_content_source_find(input+7,4,&result));
    CHECK(func_0043f810(output,input,32)==output);
    CHECK(p4_content_source_find(output,32,&result));
    input[0]^=1; /* an unobserved compiler-emitted write invalidates attribution */
    CHECK(!p4_content_source_find(input,32,&result));
    CHECK(p4_content_source_find(output,32,&result));
    p4_content_source_mark(input,16,&disc);
    p4_content_source_mark(input+16,16,&mod);
    CHECK(!p4_content_source_find(input,32,&result));
    CHECK(p4_content_source_find(input+16,16,&result) && result.rank==3);
    /* Overlap must capture the source before memmove invalidates/mutates it. */
    CHECK(func_0043f8c0(output+4,output,16)==output+4);
    CHECK(p4_content_source_find(output+4,16,&result));
    CHECK(result.origin==P4_TEXTURE_DISC);
    CHECK(func_0043f9c8(output+6,0,1)==output+6);
    CHECK(!p4_content_source_find(output+4,16,&result));
    /* Notify lifetime end without clearing or reading the released allocation. */
    p4pc_bytes_invalidate(input,sizeof input);
    CHECK(!p4_content_source_find(input,16,&result));
    CHECK(input[0]==1);
    for (size_t i=1;i<sizeof input;++i) CHECK(input[i]==(uint8_t)i);
    p4_content_host_read_end(&outputScope);
    CHECK(!p4_content_host_read_contains(output,1));
    /* Source verification and adjacency work across bounded chunk snapshots. */
    p4_content_source_mark(chunks,sizeof chunks,&disc);
    CHECK(p4_content_source_find(chunks+65530,10,&result));
    chunks[65535]=1;
    CHECK(!p4_content_source_find(chunks+65530,10,&result));
    CHECK(p4_content_source_find(chunks+65536,4,&result));
    p4_content_source_forget(chunks,sizeof chunks);
    /* Metadata pressure evicts old attribution, never misidentifies new data. */
    for (unsigned i=0;i<4097;++i) p4_content_source_mark(many+i*4,4,&disc);
    CHECK(!p4_content_source_find(many,4,&result));
    CHECK(p4_content_source_find(many+4096*4,4,&result));
    p4_content_source_forget(many,sizeof many);
    CHECK(p4_content_sources_enable(0,NULL)==0);
    CHECK(!p4_content_sources_enabled);
    puts("content_source: streaming SHA-256, verified origin, mutation and lifetime passed");
    return 0;
}
